<?php require 'admin_guard.php';require 'admin_db.php';$q=trim($_GET['q']??'');$sql="SELECT r.repoID,r.coursecode,r.name,COUNT(rr.resourceID) content_count FROM repository r LEFT JOIN resource_uploaded_in_repo rr ON rr.repoID=r.repoID WHERE r.repoID LIKE ? OR r.coursecode LIKE ? OR r.name LIKE ? GROUP BY r.repoID,r.coursecode,r.name ORDER BY r.coursecode";$s=mysqli_prepare($conn,$sql);$like="%$q%";mysqli_stmt_bind_param($s,'sss',$like,$like,$like);mysqli_stmt_execute($s);$rows=mysqli_stmt_get_result($s);?><!doctype html><html><head><title>Repositories</title><link rel="stylesheet" href="admin_pages.css"></head><body><div class="page"><div class="top"><h1>All Repository</h1><a class="btn" href="admin_dashboard.php">Dashboard</a></div><div class="panel"><form><input name="q" value="<?=htmlspecialchars($q)?>" placeholder="Search repo ID, course code or repo name"><button>Search</button></form></div><div class="panel tablewrap"><table><tr><th>Repo ID</th><th>Course</th><th>Name</th><th>Content Rows</th><th>Actions</th></tr><?php while($r=mysqli_fetch_assoc($rows)):?><tr><td><?=$r['repoID']?></td><td><?=$r['coursecode']?></td><td><?=htmlspecialchars($r['name'])?></td><td><?=$r['content_count']?></td><td><a class="btn" href="edit_repository.php?repoID=<?=urlencode($r['repoID'])?>">Update</a></td></tr><?php endwhile;?></table></div><div class="panel"><a class="btn" href="insert_repository.php">＋ Add Repository</a></div></div></body></html>
